{"content": "class Controller:
    def __init__(self):
        self.generation = 0
        self.rows = []
        self.decisions = {}
        self.busy = False
        self._finished = False
        self._polled = False

    def start(self):
        self.generation += 1
        self.busy = True
        # Preserve rows and decisions across start()
        self._finished = False
        self._polled = False
        return self.generation

    def poll_status(self, generation, status):
        # Stale generation
        if generation != self.generation:
            return False
        # Duplicate poll — already returned True for this generation
        if self._polled:
            return False
        # Status-dependent behavior
        if status == "completed":
            self._polled = True
            return True
        elif status in ("queued", "running"):
            # queued/running keep busy
            return False
        elif status == "failed":
            # failed ends busy without fetching
            self.busy = False
            return False
        else:
            # Unknown / stale status
            return False

    def finish(self, generation, rows):
        # Stale / unrequested generation
        if generation != self.generation:
            return False
        # Already finished this generation
        if self._finished:
            return False
        # Accept only latest completed pending results once
        self.rows = list(rows)  # copy rows
        self.busy = False
        self._finished = True
        return True

    def set_decision(self, job_id, value):
        self.decisions[job_id] = value"}
